import { visit } from 'unist-util-visit';
import { parseMetaString } from '../rehype/rehypeCodeBlocks/parseMetaString.js';
export const remarkWrapCodeBlocks = () => (tree) => {
    visit(tree, 'code', (node) => {
        if (node.meta && parseMetaString(node.meta).wrap === true)
            return;
        node.meta = node.meta ? `${node.meta} wrap` : 'wrap';
    });
};
